<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$pdo->exec("CREATE TABLE IF NOT EXISTS visits(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,visit_date DATE NOT NULL,visit_time TIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB");
if($_POST && isset($_POST['user_id'])){$uid=(int)$_POST['user_id'];$pdo->prepare("INSERT INTO visits(user_id,visit_date,visit_time) VALUES(?,CURDATE(),CURTIME())")->execute([$uid]);setmsg('Kunjungan berhasil dicatat.');}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare("SELECT v.*,u.name,u.username,u.class_name FROM visits v JOIN users u ON u.id=v.user_id WHERE v.visit_date BETWEEN ? AND ? ORDER BY v.visit_date DESC,v.visit_time DESC");$s->execute([$from,$to]);$rows=$s->fetchAll();
$members=$pdo->query("SELECT id,name,username FROM users WHERE role='anggota' AND status='aktif' ORDER BY name")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Kunjungan Perpustakaan</title><link rel=stylesheet href=../public/style.css></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>🚶 Kunjungan Perpustakaan</h1><?php msg()?><div class=form><form method=post><label>Catat Kunjungan Anggota</label><select name=user_id required><option value="">Pilih anggota</option><?php foreach($members as $m):?><option value=<?=$m['id']?>><?=e($m['name'].' ('.$m['username'].')')?></option><?php endforeach?></select><button>+ Catat Kunjungan</button></form></div><div class=form><form method=get class=grid><div><label>Dari</label><input type=date name=from value="<?=e($from)?>"></div><div><label>Sampai</label><input type=date name=to value="<?=e($to)?>"></div><div><button>Filter</button></div></form></div><table class=table><tr><th>No</th><th>Anggota</th><th>Kelas</th><th>Tanggal</th><th>Jam</th></tr><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['name'])?></td><td><?=e($r['class_name'])?></td><td><?=$r['visit_date']?></td><td><?=$r['visit_time']?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan=5>Tidak ada kunjungan pada periode tersebut.</td></tr><?php endif?></table></main></div></body></html>